+             uni:worksIn ?department .
+
+  # Full professors are represented by roles beginning with "Professor";
+  # assistant professors begin with "Assistant Professor".
+  FILTER (STRSTARTS(STR(?role), "Professor"))
+
+  ?department a uni:Department ;
+              uni:belongsTo ?university .
+  ?university uni:locatedInCountry ?country .
+
+  # At least one department where the professor works must be in the EU.
+  FILTER EXISTS {
+    ?professor uni:worksIn ?euDepartment .
