+      "MT" "NL" "PL" "PT" "RO" "SK" "SI" "ES" "SE"
+    }
+  }
+
+  # Join only professors having a department with more than 10
+  # distinct students currently enrolled in its courses.
+  {
+    SELECT ?professor ?busyDepartment
